namespace Titan.Domain.Aggregates.Platform.ProviderClientIdentity;

// Titan's TLS client certificate toward every Incus cluster, generated by the control plane
// (https://github.com/OpenViCloud/titan-ops/blob/main/docs/features/cluster/design.md#provider-client-identity). The private key arrives encrypted; this
// aggregate never sees it in plaintext. One row under a fixed id: a second identity would leave every cluster that
// trusts the first one refusing Titan.
public class ProviderClientIdentity
{
    public static readonly Guid SingletonId = new("7174616e-0000-4000-8000-000000000001");

    public Guid Id { get; private set; }
    public string CertificatePem { get; private set; } = default!;
    public byte[] KeyCipher { get; private set; } = default!;
    public string Fingerprint { get; private set; } = default!;
    public DateTimeOffset CreatedAt { get; private set; }

    private ProviderClientIdentity() { }

    public static ProviderClientIdentity Create(string certificatePem, byte[] keyCipher, string fingerprint)
    {
        if (certificatePem is null)
        {
            throw new ArgumentException("certificatePem must not be null", nameof(certificatePem));
        }
        bool isACertificate = certificatePem.Contains("-----BEGIN CERTIFICATE-----")
            && !certificatePem.Contains("PRIVATE KEY");
        if (!isACertificate)
        {
            throw new ArgumentException("certificatePem must hold a certificate and no private key", nameof(certificatePem));
        }
        if (keyCipher is null || keyCipher.Length == 0)
        {
            throw new ArgumentException("keyCipher must not be empty", nameof(keyCipher));
        }
        if (fingerprint is null)
        {
            throw new ArgumentException("fingerprint must not be null", nameof(fingerprint));
        }
        bool isSha256Hex = fingerprint.Length == 64
            && fingerprint.All(c => char.IsAsciiDigit(c) || (c >= 'a' && c <= 'f'));
        if (!isSha256Hex)
        {
            throw new ArgumentException("fingerprint must be 64 lower-case hex digits", nameof(fingerprint));
        }

        return new ProviderClientIdentity
        {
            Id = SingletonId,
            CertificatePem = certificatePem,
            KeyCipher = keyCipher,
            Fingerprint = fingerprint,
            CreatedAt = DateTimeOffset.UtcNow,
        };
    }
}
